import fs from 'node:fs';import {createHash} from 'node:crypto';
const base='research/election-baseline-v1',sha=b=>createHash('sha256').update(b).digest('hex');
const files=['execution/production-activation.mjs','execution/production-authority.test.mjs','execution/production-reconciliation.mjs','execution/production-reconciliation.test.mjs','execution/production-launch.md','execution/README.md','live-paper/transport-network-budget.mjs','live-paper/runner.mjs','coordination/execution_state.json','docs/COORDINATION.md','data/reconcile-production-human-20261004.mjs','data/prepare-human-assignment-publication-20261004.mjs',...['README.md','definition.json','definition-before-house-access.json','download-sources.mjs','model.mjs','model.test.mjs','train.mjs','current-inputs.json','model-summary.json','source-crosschecks.json','sources/PEJ5QU-manifest.json','sources/42MVDX-manifest.json'].map(f=>base+'/'+f)];
const pack='data/human-assignment-publication-pack-20261004.json',arg=process.argv.indexOf('--chunk');
if(arg!==-1){const bytes=fs.readFileSync(pack,'utf8'),n=Number(process.argv[arg+1]);if(!Number.isSafeInteger(n)||n<0)throw Error('CHUNK');console.log(JSON.stringify(bytes.slice(n*10000,(n+1)*10000)));}
else{
 const r=JSON.parse(fs.readFileSync(base+'/model-report.json')),summary={...Object.fromEntries(['schemaVersion','id','at','definitionHash','sourceManifests','sourceIntegrityVerified','rows','includedCycles','selectedLambda','selectedUsingYearsThrough','residualRms','model','modelHash','check','forecasts','forecastVintagesAvailable','pollingTransportValidatedByHistoricalCheck','calibrationEstablishedFor2026','qualifiedProductionForecasts','ordersSubmitted','paperFills','profitabilityEstablished','limitations'].map(k=>[k,r[k]])),fullLocalReportSha256:sha(fs.readFileSync(base+'/model-report.json')),excludedRaces:r.exclusions.length,development:r.development.map(d=>({lambda:d.lambda,metrics:d.metrics,cycleMse:d.cycleMse})),additionalReviewLimitations:['Screened historical two-party probabilities are not unconditional party-win forecasts when a third-party candidate can win.','WV current official ballot has S.Marshall Wilson(CST); original draft candidate alias Rachel Anderson is Rachel Fetty Anderson on the official ballot.','No fresh source eligibility is created by publishing this summary.']};
 if(!fs.existsSync(base+'/model-summary.json'))fs.writeFileSync(base+'/model-summary.json',JSON.stringify(summary,null,2)+'\n',{flag:'wx'});
 const elements=files.map(path=>{const content=fs.readFileSync(path,'utf8');if(/ace_[a-f0-9]{30,}|sk-[a-zA-Z0-9_-]{20,}|-----BEGIN [A-Z ]*PRIVATE KEY-----|https:\/\/[^\s"']+token=[A-Za-z0-9%]+/i.test(content))throw Error('SECRET_CHECK '+path);return{path,mode:'100644',type:'blob',content};});
 const bytes=JSON.stringify(elements);fs.writeFileSync(pack,bytes);console.log(JSON.stringify({files:files.length,characters:bytes.length,chunks:Math.ceil(bytes.length/10000),sha256:sha(bytes)}));
}
